package de.kopfzentrum.gam.settings;
import de.kopfzentrum.gam.auth.AuthenticatedUser;import org.springframework.http.HttpStatus;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/settings/compliance-workflow") public class ComplianceWorkflowSettingsController {private final ComplianceWorkflowSettingsRepository repo;public ComplianceWorkflowSettingsController(ComplianceWorkflowSettingsRepository repo){this.repo=repo;}@GetMapping public ComplianceWorkflowSettings get(@AuthenticationPrincipal AuthenticatedUser u){req(u);return repo.load();}@PutMapping public ComplianceWorkflowSettings put(@RequestBody ComplianceWorkflowSettings v,@AuthenticationPrincipal AuthenticatedUser u){req(u);return repo.save(v,u.getUsername());}private void req(AuthenticatedUser u){if(u==null)throw new ResponseStatusException(HttpStatus.FORBIDDEN);}}
